package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Opens each selected claim in list order (people by their list positions, newest claim first within a
 * person); one that cannot be opened is left as it is and counted refused.
 */
public class BulkOpenClaims {
    public void open(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @RequestBody BulkOpenRequest request, Claims claims, People people, ClaimStatusChanger changer,
            ObjectResponse<BulkOpenResponse> response) {
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.id(), personOrder.size());
        }
        List<Claim> selected = new ArrayList<>();
        int refused = 0;
        for (Long id : new LinkedHashSet<>(request == null || request.claims() == null ? List.of() : request.claims())) {
            Claim claim = id == null ? null : claims.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        // Newest first within a person, as the sheet lists them.
        Map<Long, Integer> listOrder = new HashMap<>();
        for (Claim claim : claims.list(sheet)) {
            listOrder.put(claim.id(), listOrder.size());
        }
        selected.sort(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.person(), Integer.MAX_VALUE))
                .thenComparing((Claim c) -> listOrder.getOrDefault(c.id(), Integer.MAX_VALUE)));
        int opened = 0;
        for (Claim claim : selected) {
            try {
                // Re-read so each claim is opened as the store holds it after the ones before it.
                changer.change(sheet, user, claims.find(sheet, claim.id()), ClaimStatusChange.OPEN);
                opened++;
            } catch (InvalidClaimStatusChangeException refusal) {
                refused++;
            }
        }
        response.send(new BulkOpenResponse(opened, refused, claims.list(sheet)));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the status the change takes it to, refusing a change its status does not allow; a settle
 *  with a date is as of that day. */
public class ApplyClaimStatus {
    public void apply(@PathVariable("sheet") String sheet, @PathVariable("change") String change,
            @RequestParam("user") String user, @RequestBody ClaimStatusRequest body, @Val Claim claim,
            ClaimStatusChanger changer, Claims claims, ClaimDueAsOf dueAsOf, SheetClock clock) throws InvalidClaimStatusChangeException {
        ClaimStatusChange requested = ClaimStatusChange.of(change);
        if (requested == null) {
            throw new InvalidClaimStatusChangeException("No such status change: " + change);
        }
        String on = body == null || body.on() == null ? "" : body.on().trim();
        if (requested == ClaimStatusChange.SETTLE && !on.isEmpty()) {
            // Settled as of a date on or before the sheet's today, at the due the claim had at the end of it.
            LocalDate date;
            try {
                date = LocalDate.parse(on);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimStatusChangeException("Not a valid settle date: " + on);
            }
            if (date.isAfter(clock.today(sheet))) {
                throw new InvalidClaimStatusChangeException("A claim cannot be settled as of a date after today");
            }
            ClaimDueAsOf.Then then = dueAsOf.on(sheet, claim.id(), date);
            if (!then.existed()) {
                throw new InvalidClaimStatusChangeException("The claim did not exist on " + date);
            }
            changer.settleAsOf(sheet, user, claim, date, then.due());
        } else {
            changer.change(sheet, user, claim, requested, body == null ? null : body.reason());
        }
        if (requested == ClaimStatusChange.SETTLE) {
            // Settled one at a time: no longer part of a bulk settle batch.
            claims.setBatch(sheet, claim.id(), null);
        }
    }
}

